// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(10000, "Test", "TST"); }
    function testFuzz_property(uint256 burnAmount, address burner) public {
        vm.assume(burner != address(0));
        vm.assume(burnAmount > 0);
        vm.assume(c.balanceOf(c.owner()) >= burnAmount);
        vm.prank(c.owner());
        c.burn(burnAmount);
        uint256 sumBalances = c.balanceOf(c.owner()) + c.balanceOf(address(0)) + c.balanceOf(burner);
        assertTrue(c.totalSupply() == sumBalances);
    }
}
